package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.DimensionMismatchException;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.exception.OutOfRangeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MultidimensionalCounter_getCounts_TriageGen0Test {

    @Test
    public void testGetCounts_ValidIndex_SingleDimension() {
        // Dimension 1, size 10
        MultidimensionalCounter counter = new MultidimensionalCounter(10);
        int[] expected = {3};
        assertArrayEquals(expected, counter.getCounts(3));

        int[] expectedZero = {0};
        assertArrayEquals(expectedZero, counter.getCounts(0));

        int[] expectedLast = {9};
        assertArrayEquals(expectedLast, counter.getCounts(9));
    }

    @Test
    public void testGetCounts_ValidIndex_MultiDimension() {
        // Dimensions 2, 3x4 = 12 total size
        // Dimensions: [3, 4]
        // uniCounterOffset would be [4, 1] (depending on internal implementation logic)
        // Let's assume standard odometer/lexicographical order:
        // index 0: [0,0], index 1: [0,1], index 2: [0,2], index 3: [0,3], index 4: [1,0]...
        MultidimensionalCounter counter = new MultidimensionalCounter(3, 4);

        // Test first element
        assertArrayEquals(new int[]{0, 0}, counter.getCounts(0));

        // Test middle element
        // index 5 -> [1, 1]
        assertArrayEquals(new int[]{1, 1}, counter.getCounts(5));

        // Test last element
        // index 11 -> [2, 3]
        assertArrayEquals(new int[]{2, 3}, counter.getCounts(11));
    }

    @Test
    public void testGetCounts_ValidIndex_ThreeDimensions() {
        // Dimensions 2x2x2 = 8
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 2, 2);

        // index 7 -> [1, 1, 1]
        assertArrayEquals(new int[]{1, 1, 1}, counter.getCounts(7));

        // index 3 -> [0, 1, 1]
        assertArrayEquals(new int[]{0, 1, 1}, counter.getCounts(3));
    }

    @Test(expected = OutOfRangeException.class)
    public void testGetCounts_IndexTooSmall() {
        MultidimensionalCounter counter = new MultidimensionalCounter(5, 5);
        counter.getCounts(-1);
    }

    @Test(expected = OutOfRangeException.class)
    public void testGetCounts_IndexTooLarge() {
        MultidimensionalCounter counter = new MultidimensionalCounter(5, 5);
        // totalSize is 25, so 25 is out of bounds
        counter.getCounts(25);
    }

    @Test
    public void testGetCounts_BoundarySizeOne() {
        MultidimensionalCounter counter = new MultidimensionalCounter(1);
        assertArrayEquals(new int[]{0}, counter.getCounts(0));
    }

    @Test
    public void testGetCounts_ComplexDimensions() {
        // Testing with non-uniform sizes to ensure the offset logic works
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 5, 3);
        // Total size = 30
        // index 29 should be [1, 4, 2]
        assertArrayEquals(new int[]{1, 4, 2}, counter.getCounts(29));
        // index 10: 
        // 10 / (5*3) = 0 rem 10
        // 10 / 3 = 3 rem 1
        // Result [0, 3, 1]
        assertArrayEquals(new int[]{0, 3, 1}, counter.getCounts(10));
    }
}
